window.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll('a[href^="tel:"], a[href^="mailto:"]').forEach(e=>{e.addEventListener("click",()=>{if(typeof window.gtag!="function")return;const t=(e.getAttribute("href")||"").startsWith("tel:"),n=t?"phone_click":"email_click";window.gtag("event",n,{contact_method:t?"phone":"email",page_path:window.location.pathname,page_title:document.title})})})});
